const hqObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');hqObserver.unobserve(e.target)}}),{threshold:.15});document.querySelectorAll('.hq-annotation').forEach(e=>hqObserver.observe(e));document.querySelectorAll('[data-research-image]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#viewer-image').src=b.dataset.researchImage;document.querySelector('#viewer-title').textContent=b.querySelector('img').alt;document.querySelector('#viewer-image').alt=b.querySelector('img').alt;document.querySelector('#viewer').showModal()}));document.querySelectorAll('.hq-callout').forEach(b=>b.addEventListener('click',()=>{const stage=b.closest('.hq-annotation-stage'),ring=stage.querySelector('.hq-focus-ring'),phone=stage.querySelector('.hq-phone');ring.style.top=(30+phone.offsetHeight*Number(b.dataset.focusY)/100-20)+'px';ring.classList.remove('pulse');void ring.offsetWidth;ring.classList.add('pulse')}));
